tool_calls:
cd /home/eval/recon; mkdir -p out; cat > recon.awk <<'EOF'
function cents(s,   neg,ip,fp,n,p){
  gsub(/[ ,\r]/,"",s); neg=0
  if (s ~ /^-/){neg=1; s=substr(s,2)} else if (s ~ /^\+/) s=substr(s,2)
  n=index(s,"."); if(n){ip=substr(s,1,n-1); fp=substr(s,n+1)} else {ip=s; fp=""}
  if(ip=="") ip="0"
  fp=fp "000"; c=ip*100+substr(fp,1,2)+0
  if (substr(fp,3,1)+0>=5) c++
  return neg?-c:c
}
function fmt(c,  s){ s=(c<0)?"-":""; if(c<0)c=-c; return sprintf("%s%d.%02d",s,int(c/100),c%100) }
function parsecsv(line, f,   n,i,ch,inq,cur){
  n=0; cur=""; inq=0
  for(i=1;i<=length(line);i++){ ch=substr(line,i,1)
    if(inq){ if(ch=="\""){ if(substr(line,i+1,1)=="\""){cur=cur "\""; i++} else inq=0 } else cur=cur ch }
    else if(ch=="\"") inq=1
    else if(ch==","){ f[++n]=cur; cur="" }
    else cur=cur ch }
  f[++n]=cur; return n
}
FNR==1{next}
FILENAME ~ /ledger/ { sub(/\r$/,""); if($0=="")next; parsecsv($0,f); id=f[1]; gsub(/^ +| +$/,"",id)
  lr++; la[id]=cents(f[4]); ld[id]=f[2]; gsub(/ /,"",ld[id]); lt+=la[id]; next }
{ sub(/\r$/,""); if($0=="")next; split($0,f,"\t"); id=toupper(f[1]); gsub(/^ +| +$/,"",id)
  d=f[2]; gsub(/ /,"",d); split(d,p,"/"); d=p[3] "-" p[2] "-" p[1]; a=cents(f[4])
  k=id SUBSEP d SUBSEP a; if(k in seen){dup++; next}; seen[k]=1
  br++; ba[id]=a; bd[id]=d; bt+=a }
END{
  printf "ledger_rows: %d\nbank_rows: %d\nduplicate_bank_rows: %d\nledger_total: %s\nbank_total: %s\n", lr,br,dup+0,fmt(lt),fmt(bt)
  n=0; for(id in la) ids[++n]=id
  for(i=2;i<=n;i++){x=ids[i];for(j=i-1;j>=1&&ids[j]>x;j--)ids[j+1]=ids[j];ids[j+1]=x}
  m=0; for(id in ba) bids[++m]=id
  for(i=2;i<=m;i++){x=bids[i];for(j=i-1;j>=1&&bids[j]>x;j--)bids[j+1]=bids[j];bids[j+1]=x}
  mt=0;ac=0;dc=0;mc=0;lc=0;A="";D="";M="";L=""
  for(i=1;i<=n;i++){id=ids[i]
    if(!(id in ba)){mc++; M=M "  " id "\n"; continue}
    if(la[id]!=ba[id]){ac++; A=A "  " id " ledger=" fmt(la[id]) " bank=" fmt(ba[id]) "\n"}
    if(ld[id]!=bd[id]){dc++; D=D "  " id " ledger=" ld[id] " bank=" bd[id] "\n"}
    if(la[id]==ba[id]&&ld[id]==bd[id]) mt++ }
  for(i=1;i<=m;i++) if(!(bids[i] in la)){lc++; L=L "  " bids[i] "\n"}
  printf "matched: %d\namount_mismatch: %d\n%sdate_mismatch: %d\n%smissing_in_bank: %d\n%smissing_in_ledger: %d\n%s", mt,ac,A,dc,D,mc,M,lc,L
}
EOF
LC_ALL=C awk -f recon.awk ledger.csv bank.tsv > out/reconciliation.txt; cat -A out/reconciliation.txt

